   [32]={next_id=33, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻身上的星源之力澎湃，粉尘一粒接一粒地被从吉娜的血管中拔出，在空气中化为淡淡的蓝色烟雾消散。当最后一粒粉尘消散时，吉娜和吉尔的呼吸明显平稳了许多。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_102.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
